/* ---------- Helpers communs ---------- */
(function(D){
  D.lang="fr";
  var _ansByLen=null;
  function group(a){var m={};for(var i=0;i<a.length;i++){var L=a[i].length;(m[L]||(m[L]=[])).push(a[i]);}return m;}
  D.byLength=function(len){ _ansByLen=_ansByLen||group(D.answers); return _ansByLen[len]||[]; };
  D.pick=function(len){var p=D.byLength(len);return p.length?p[(Math.random()*p.length)|0]:null;};

  /* ---------- Anti-repetition (historique par jeu, localStorage) ---------- */
  function _lsGet(k){ try{ return JSON.parse(localStorage.getItem(k)||"[]"); }catch(e){ return []; } }
  function _lsSet(k,v){ try{ localStorage.setItem(k, JSON.stringify(v)); }catch(e){} }
  function _histKey(gameKey){ return "flc_seen_"+gameKey+"_"+D.lang; }
  D.seenList=function(gameKey){ return _lsGet(_histKey(gameKey)); };
  D.markSeen=function(gameKey, word){
    word=(word||"").toUpperCase(); if(!word) return;
    var key=_histKey(gameKey); var seen=_lsGet(key);
    var i=seen.indexOf(word); if(i>=0) seen.splice(i,1);
    seen.push(word); _lsSet(key, seen);
  };
  D.resetSeen=function(gameKey){ _lsSet(_histKey(gameKey), []); };
  D.pickFreshFrom=function(gameKey, pool){
    if(!pool || !pool.length) return null;
    var key=_histKey(gameKey); var seen=_lsGet(key);
    var seenSet={}; for(var i=0;i<seen.length;i++) seenSet[seen[i]]=1;
    var avail=[]; for(var j=0;j<pool.length;j++){ if(!seenSet[pool[j]]) avail.push(pool[j]); }
    if(!avail.length){
      var drop=Math.max(1, Math.floor(seen.length/2)); seen=seen.slice(drop); _lsSet(key, seen);
      seenSet={}; for(var k=0;k<seen.length;k++) seenSet[seen[k]]=1;
      avail=[]; for(var m=0;m<pool.length;m++){ if(!seenSet[pool[m]]) avail.push(pool[m]); }
      if(!avail.length) avail=pool.slice();
    }
    var w=avail[(Math.random()*avail.length)|0]; D.markSeen(gameKey, w); return w;
  };
  D.pickFresh=function(gameKey, len){ return D.pickFreshFrom(gameKey, D.byLength(len)); };

  /* ---------- Difficulte ---------- */
  /* D.easy = mots "courants" (rang de frequence reel, mots pleins), ordonnes du + au - frequent.
     On l'utilise comme reference d'ordre. Le pool "courant" d'un jeu = la moitie la plus
     frequente de SON pool, limitee aux mots reellement frequents (pas de remplissage force).   */
  var _easyRank=null;
  function easyRank(){
    if(_easyRank) return _easyRank;
    _easyRank={}; for(var i=0;i<D.easy.length;i++) _easyRank[D.easy[i]]=i;
    return _easyRank;
  }
  var _easyByLen=null;
  D.easyByLength=function(len){ _easyByLen=_easyByLen||group(D.easy); return _easyByLen[len]||[]; };

  /* Renvoie la sous-liste "courante" (la plus frequente) d'un pool donne.
     courant = min(50% du pool, nb de mots frequents du pool), pris par frequence croissante. */
  D.courantOf=function(pool){
    if(!pool || !pool.length) return [];
    var R=easyRank();
    var ranked=[];
    for(var i=0;i<pool.length;i++){ var r=R[pool[i]]; if(r!==undefined) ranked.push([r,pool[i]]); }
    ranked.sort(function(a,b){return a[0]-b[0];});
    var half=Math.floor(pool.length/2);
    var n=Math.min(half, ranked.length);
    var out=[]; for(var k=0;k<n;k++) out.push(ranked[k][1]);
    return out;
  };

  /* Pool selon difficulte, a partir du pool de base du jeu (basePool) :
       "facile"    -> moitie courante du basePool
       "moyen"     -> 1 chance sur 2 : courant, sinon basePool complet
       "difficile" -> basePool complet
     Si basePool non fourni, on retombe sur answers (filtre par longueur si len>0).        */
  D.poolFor=function(difficulty, len, basePool){
    var base = basePool ? basePool : (len ? D.byLength(len) : D.answers);
    if(difficulty==="difficile") return base;
    var cour = D.courantOf(base);
    if(difficulty==="facile") return cour.length ? cour : base;
    /* moyen */
    return (cour.length && Math.random()<0.5) ? cour : base;
  };
  /* Pioche un mot selon la difficulte, sans repetition (anti-repetition par jeu).
     basePool = pool de base du jeu (optionnel ; sinon answers filtre par len).            */
  D.pickByDifficulty=function(gameKey, difficulty, len, basePool){
    return D.pickFreshFrom(gameKey, D.poolFor(difficulty, len, basePool));
  };
})(window.DICT_FR);
